import{_ as a,o as e,c as d,a2 as o}from"./chunks/framework.BXzK3EA4.js";const b=JSON.parse('{"title":"基本信息","description":"","frontmatter":{"title":"基本信息"},"headers":[],"relativePath":"api/overview/basics.md","filePath":"api/overview/basics.md","lastUpdated":1795698978000}'),r={name:"api/overview/basics.md"};function s(i,t,c,p,l,n){return e(),d("div",null,[...t[0]||(t[0]=[o('<h2 id="接入地址" tabindex="-1">接入地址 <a class="header-anchor" href="#接入地址" aria-label="Permalink to &quot;接入地址&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://rak-api.raksmart.com/rakapi/v2</span></span></code></pre></div><p>本文档中所有接口路径均相对于上述地址。例如 <code>GET /vps</code> 的完整地址为 <code>https://rak-api.raksmart.com/rakapi/v2/vps</code>。</p><h2 id="协议" tabindex="-1">协议 <a class="header-anchor" href="#协议" aria-label="Permalink to &quot;协议&quot;">​</a></h2><p>API 仅支持 HTTPS，要求 TLS 1.2 及以上版本。使用 HTTP 发起的请求将无法建立连接。</p><h2 id="数据格式" tabindex="-1">数据格式 <a class="header-anchor" href="#数据格式" aria-label="Permalink to &quot;数据格式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>请求体</td><td>JSON，请求头需携带 <code>Content-Type: application/json</code></td></tr><tr><td>响应体</td><td>JSON</td></tr><tr><td>字符编码</td><td>UTF-8</td></tr><tr><td>字段命名</td><td>字段名均为小写字母</td></tr></tbody></table><h2 id="版本" tabindex="-1">版本 <a class="header-anchor" href="#版本" aria-label="Permalink to &quot;版本&quot;">​</a></h2><p>当前 API 版本为 <strong>v2</strong>，版本号包含在接入地址的路径中（<code>/rakapi/v2</code>）。</p><h2 id="资源标识" tabindex="-1">资源标识 <a class="header-anchor" href="#资源标识" aria-label="Permalink to &quot;资源标识&quot;">​</a></h2><p>调用接口时，需要通过 ID 指定要操作的资源：</p><table tabindex="0"><thead><tr><th>资源</th><th>标识</th><th>获取方式</th></tr></thead><tbody><tr><td>VPS、裸机云、独立服务器</td><td>服务 ID</td><td>对应产品的列表接口，或 <code>GET /services</code></td></tr><tr><td>独立云盘</td><td>服务 ID</td><td><code>GET /volumes</code></td></tr><tr><td>弹性 IP</td><td>服务 ID</td><td><code>GET /elastic-ips</code></td></tr><tr><td>快照</td><td>快照 UUID</td><td><code>GET /snapshots</code></td></tr></tbody></table><p>服务 ID 是一个整数，可通过上表中的列表接口获取。</p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>一个服务 ID 对应一个具体的产品实例。例如一台 VPS 的服务 ID 为 <code>12345</code>，则查询其详情的接口为 <code>GET /vps/12345</code>。</p></div>',14)])])}const v=a(r,[["render",s]]);export{b as __pageData,v as default};
